    "css": ".card {\n  width: 320px;\n  background: #fff480;\n  color: black;\n  position: relative;\n  border-radius: 2.5em;\n  padding: 2em;\n  transition: transform 0.4s ease;\n}\n\n.card .card-content {\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  gap: 5em;\n  height: 100%;\n  transition: transform 0.4s ease;\n}\n\n.card .card-top, .card .card-bottom {\n  display: flex;\n  justify-content: space-between;\n}\n\n.card .card-top p, .card .card-top .card-title, .card .card-bottom p, .card .card-bottom .card-title {\n  margin: 0;\n}\n\n.card .card-title {\n  font-weight: bold;\n}\n\n.card .card-top p, .card .card-bottom p {\n  font-weight: 600;\n}\n\n.card .card-bottom {\n  align-items: flex-end;\n}\n\n.card .card-image {\n  position: absolute;\n  width: 100%;\n  height: 100%;\n  top: 0;\n  left: 0;\n  display: grid;\n  place-items: center;\n  pointer-events: none;\n}\n\n.card .card-image svg {\n  width: 4em;\n  height: 4em;\n  transition: transform 0.4s ease;\n}\n\n.card:hover {\n  cursor: pointer;\n  transform: scale(0.97);\n}\n\n.card:hover .card-content {\n  transform: scale(0.96);\n}\n\n.card:hover .card-image svg {\n  transform: scale(1.05);\n}\n\n.card:active {\n  transform: scale(0.9);\n}"
