    "css": ".main-container {\n  font-family: \"Trebuchet MS\", sans-serif;\n  position: relative;\n  height: 203px;\n  aspect-ratio: 1.579;\n  border-radius: 1em;\n  overflow: hidden;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: all 300ms ease-in;\n}\n.main-container:hover {\n  transform: rotateZ(1deg) rotateY(10deg) scale(1.1);\n  box-shadow: 0 5em 2em #111;\n}\n\n.border {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 1em;\n  background: linear-gradient(\n    115deg,\n    rgba(0, 0, 0, 0.33) 12%,\n    rgba(255, 255, 255, 0.33) 27%,\n    rgba(255, 255, 255, 0.33) 31%,\n    rgba(0, 0, 0, 0.33) 52%\n  );\n}\n\n.border:hover:after {\n  position: absolute;\n  content: \" \";\n  height: 50em;\n  aspect-ratio: 1.58;\n  border-radius: 1em;\n  background: linear-gradient(\n    115deg,\n    rgba(0, 0, 0, 1) 42%,\n    rgba(255, 255, 255, 1) 47%,\n    rgba(255, 255, 255, 1) 51%,\n    rgba(0, 0, 0, 1) 52%\n  );\n  animation: rotate 4s linear infinite;\n  z-index: 1;\n  opacity: 0.05;\n}\n\n.card {\n  height: 12.5em;\n  aspect-ratio: 1.586;\n  border-radius: 1em;\n  background-color: #999;\n  opacity: 0.8;\n  background-image: linear-gradient(to right, #777, #777 2px, #999 2px, #999);\n  background-size: 4px 100%;\n}\n\n.shadow {\n  position: relative;\n  width: 100%;\n  height: 100%;\n  border-radius: 0.85em;\n  border: 1px solid #bbb;\n  background:\n    radial-gradient(\n        circle at 100% 100%,\n        #ffffff 0,\n        #ffffff 8px,\n        transparent 8px\n      )\n      0% 0%/13px 13px no-repeat,\n    radial-gradient(circle at 0 100%, #ffffff 0, #ffffff 8px, transparent 8px)\n      100% 0%/13px 13px no-repeat,\n    radial-gradient(circle at 100% 0, #ffffff 0, #ffffff 8px, transparent 8px)\n      0% 100%/13px 13px no-repeat,\n    radial-gradient(circle at 0 0, #ffffff 0, #ffffff 8px, transparent 8px) 100%\n      100%/13px 13px no-repeat,\n    linear-gradient(#ffffff, #ffffff) 50% 50% / calc(100% - 10px)\n      calc(100% - 26px) no-repeat,\n    linear-gradient(#ffffff, #ffffff) 50% 50% / calc(100% - 26px)\n      calc(100% - 10px) no-repeat,\n    linear-gradient(\n      135deg,\n      rgba(3, 3, 3, 0.5) 0%,\n      transparent 22%,\n      transparent 47%,\n      transparent 73%,\n      rgba(0, 0, 0, 0.5) 100%\n    );\n  box-sizing: border-box;\n}\n\n.content {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  border-radius: 0.6em;\n  border: 1px solid #aaa;\n  box-shadow: -1px -1px 0 #ddd;\n  transform: translate(-50%, -50%);\n  height: 12em;\n  aspect-ratio: 1.604;\n  background-image: linear-gradient(to right, #777, #555 2px, #aaa 2px, #aaa);\n  background-size: 4px 100%;\n}\n\n.rev {\n  top: 0.5em;\n  left: 0.75em;\n  color: #ffffff9f;\n  font-size: 1.25em;\n}\n\n.master {\n  position: absolute;\n  bottom: 1.25em;\n  right: 0.5em;\n  background: linear-gradient(\n    90deg,\n    rgba(75, 75, 75, 0.25) 0%,\n    rgba(121, 121, 121, 1) 100%\n  );\n  color: #fff;\n  height: 2.5em;\n  width: 2.5em;\n  border: 1px solid #bbb;\n  border-radius: 50%;\n}\n\n.master.one {\n  right: 2em;\n}\n\n.master-text {\n  bottom: 0.25em;\n  right: 0.8em;\n  font-size: 0.75em;\n}\n\n.ultra-text {\n  top: -4px;\n  right: 1.75em;\n  font-size: 0.5em;\n  color: rgba(255, 255, 255, 0.66);\n}\n\n.ultra-text,\n.master-text,\n.rev {\n  position: absolute;\n  text-shadow: -1px -1px #333;\n  color: #fff;\n  opacity: 0.75;\n}\n\n.chip {\n  position: absolute;\n  top: 27.5%;\n  left: 8.25%;\n}\n\n@keyframes rotate {\n  0% {\n    transform: translate(-25em, -15em);\n  }\n  20% {\n    transform: translate(25em, 15em);\n  }\n  100% {\n    transform: translate(25em, 15em);\n  }\n}\n"
