    "css": ".card {\n  margin-left: -1rem;\n  margin-right: -1rem;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: stretch;\n  margin-bottom: 2rem;\n  width: 320px;\n  display: flex;\n  flex-direction: column;\n  border-radius: 0.25rem;\n  background-color: rgba(17, 24, 39, 1);\n  padding: 1.5rem;\n}\n\n.header {\n  display: flex;\n  flex-direction: column;\n}\n\n.title {\n  font-size: 1.5rem;\n  line-height: 2rem;\n  font-weight: 700;\n  color: #fff\n}\n\n.price {\n  font-size: 3.75rem;\n  line-height: 1;\n  font-weight: 700;\n  color: #fff\n}\n\n.desc {\n  margin-top: 0.75rem;\n  margin-bottom: 0.75rem;\n  line-height: 1.625;\n  color: rgba(156, 163, 175, 1);\n}\n\n.lists {\n  margin-bottom: 1.5rem;\n  flex: 1 1 0%;\n  color: rgba(156, 163, 175, 1);\n}\n\n.lists .list {\n  margin-bottom: 0.5rem;\n  display: flex;\n  margin-left: 0.5rem\n}\n\n.lists .list svg {\n  height: 1.5rem;\n  width: 1.5rem;\n  flex-shrink: 0;\n  margin-right: 0.5rem;\n  color: rgba(167, 139, 250, 1);\n}\n\n.action {\n  border: none;\n  outline: none;\n  display: inline-block;\n  border-radius: 0.25rem;\n  background-color: rgba(167, 139, 250, 1);\n  padding-left: 1.25rem;\n  padding-right: 1.25rem;\n  padding-top: 0.75rem;\n  padding-bottom: 0.75rem;\n  text-align: center;\n  font-weight: 600;\n  letter-spacing: 0.05em;\n  color: rgba(17, 24, 39, 1);\n}"
