    "css": ".container {\n  height: 200px;\n  width: 350px;\n  border-radius: 1em;\n  overflow: hidden;\n  box-shadow: 0 10px 20px #dbdbdb;\n  font-family: sans-serif;\n}\n\n.palette {\n  display: flex;\n  height: 86%;\n  width: 100%;\n}\n\n.color {\n  height: 100%;\n  flex: 1;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: white;\n  font-weight: 600;\n  letter-spacing: 1px;\n  transition: flex 0.1s linear;\n}\n\n.color span {\n  opacity: 0;\n  transition: opacity 0.1s linear;\n}\n\n.color:nth-child(1) {\n  background: #264653;\n}\n\n.color:nth-child(2) {\n  background: #2a9d8f;\n}\n\n.color:nth-child(3) {\n  background: #e9c46a;\n}\n\n.color:nth-child(4) {\n  background: #f4a261;\n}\n\n.color:nth-child(5) {\n  background: #e76f51;\n}\n\n.color:hover {\n  flex: 2;\n  box-shadow: rgba(100, 100, 111, 0.2) 0px 7px 29px 0px;\n}\n\n.color:hover span {\n  opacity: 1;\n}\n\n#stats {\n  height: 14%;\n  width: 100%;\n  background: white;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0 1.5em;\n  box-sizing: border-box;\n  color: #bebebe;\n}\n\n#stats svg {\n  fill: #bebebe;\n  transform: scale(1.2);\n}"
