    "css": ".card {\n  width: 300px;\n  height: 254px;\n  background: lightgrey;\n  overflow: hidden;\n  display: flex;\n}\n\n.circles,\n.browser {\n  height: 30px;\n  display: flex;\n  align-items: center;\n}\n\n.circles {\n  width: 20%;\n  gap: 8px;\n  padding: 10px;\n}\n\n.c {\n  width: 09px;\n  height: 9px;\n  border-radius: 50%;\n  box-shadow: inset 2px 2px 5px rgba(235, 235, 235, 0.356);\n}\n\n.c:first-child {\n  background-color: red;\n}\n\n.c:nth-child(2) {\n  background-color: rgb(204, 167, 4);\n}\n\n.c:last-child {\n  background-color: green;\n}\n\n.browser {\n  width: 80%;\n  padding: 5px;\n  display: flex;\n  gap: 10px;\n}\n\n.chevrons {\n  display: flex;\n}\n\n.search-bar {\n  position: relative;\n  border: 0.5px solid black;\n  border-radius: 5px;\n  padding: 5px;\n  width: 100%;\n  height: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 10px;\n  color: rgb(88, 88, 88);\n  box-shadow: inset 2px 2px 2px #05050525;\n}\n\n.search-bar svg {\n  position: absolute;\n  left: 10px;\n}"
