    "css": ".card {\n  width: 300px;\n  height: 220px;\n  background-color: rgb(255, 255, 255);\n  border-radius: 8px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  padding: 20px 30px;\n  gap: 13px;\n  position: relative;\n  overflow: hidden;\n  box-shadow: 2px 2px 20px rgba(0, 0, 0, 0.062);\n}\n\n#cookieSvg {\n  width: 50px;\n}\n\n#cookieSvg g path {\n  fill: rgb(97, 81, 81);\n}\n\n.cookieHeading {\n  font-size: 1.2em;\n  font-weight: 800;\n  color: rgb(26, 26, 26);\n}\n\n.cookieDescription {\n  text-align: center;\n  font-size: 0.7em;\n  font-weight: 600;\n  color: rgb(99, 99, 99);\n}\n\n.cookieDescription a {\n  --tw-text-opacity: 1;\n  color: rgb(59 130 246);\n}\n\n.cookieDescription a:hover {\n  -webkit-text-decoration-line: underline;\n  text-decoration-line: underline;\n}\n\n.buttonContainer {\n  display: flex;\n  gap: 20px;\n  flex-direction: row;\n}\n\n.acceptButton {\n  width: 80px;\n  height: 30px;\n  background-color: #7b57ff;\n  transition-duration: .2s;\n  border: none;\n  color: rgb(241, 241, 241);\n  cursor: pointer;\n  font-weight: 600;\n  border-radius: 20px;\n  box-shadow: 0 4px 6px -1px #977ef3, 0 2px 4px -1px #977ef3;\n  transition: all .6s ease;\n}\n\n.declineButton {\n  width: 80px;\n  height: 30px;\n  background-color: #dadada;\n  transition-duration: .2s;\n  color: rgb(46, 46, 46);\n  border: none;\n  cursor: not-allowed;\n  font-weight: 600;\n  border-radius: 20px;\n  box-shadow: 0 4px 6px -1px #bebdbd, 0 2px 4px -1px #bebdbd;\n  transition: all .6s ease;\n}\n\n.declineButton:hover {\n  background-color: #ebebeb;\n  box-shadow: 0 10px 15px -3px #bebdbd, 0 4px 6px -2px #bebdbd;\n  transition-duration: .2s;\n}\n\n.acceptButton:hover {\n  background-color: #9173ff;\n  box-shadow: 0 10px 15px -3px #977ef3, 0 4px 6px -2px #977ef3;\n  transition-duration: .2s;\n}"
