    "css": ".card {\n  max-width: 320px;\n  border-width: 1px;\n  border-color: rgba(219, 234, 254, 1);\n  border-radius: 1rem;\n  background-color: rgba(255, 255, 255, 1);\n  padding: 1rem;\n}\n\n.header {\n  display: flex;\n  align-items: center;\n  grid-gap: 1rem;\n  gap: 1rem;\n}\n\n.icon {\n  flex-shrink: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 9999px;\n  background-color: rgba(96, 165, 250, 1);\n  padding: 0.5rem;\n  color: rgba(255, 255, 255, 1);\n}\n\n.icon svg {\n  height: 1rem;\n  width: 1rem;\n}\n\n.alert {\n  font-weight: 600;\n  color: rgba(107, 114, 128, 1);\n}\n\n.message {\n  margin-top: 1rem;\n  color: rgba(107, 114, 128, 1);\n}\n\n.actions {\n  margin-top: 1.5rem;\n}\n\n.actions a {\n  text-decoration: none;\n}\n\n.mark-as-read, .read {\n  display: inline-block;\n  border-radius: 0.5rem;\n  width: 100%;\n  padding: 0.75rem 1.25rem;\n  text-align: center;\n  font-size: 0.875rem;\n  line-height: 1.25rem;\n  font-weight: 600;\n}\n\n.read {\n  background-color: rgba(59, 130, 246, 1);\n  color: rgba(255, 255, 255, 1);\n}\n\n.mark-as-read {\n  margin-top: 0.5rem;\n  background-color: rgba(249, 250, 251, 1);\n  color: rgba(107, 114, 128, 1);\n  transition: all .15s ease;\n}\n\n.mark-as-read:hover {\n  background-color: rgb(230, 231, 233);\n}"
