    "css": ".card {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  position: relative;\n  width: 220px;\n  height: 350px;\n  border-radius: 20px;\n  overflow: hidden;\n  box-shadow: 12px 12px 0px rgba(0, 0, 0, 0.1);\n  background-color: white;\n}\n\n/* Landscape section */\n.landscape-section {\n  position: relative;\n  width: 100%;\n  height: 70%;\n  overflow: hidden;\n}\n\n.landscape-section * {\n  position: absolute;\n}\n\n.sky {\n  width: 100%;\n  height: 100%;\n  background: rgb(247, 225, 87);\n  background: linear-gradient(\n    0deg,\n    rgba(247, 225, 87, 1) 0%,\n    rgba(233, 101, 148, 1) 100%\n  );\n}\n\n.sun {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 45px;\n  height: 45px;\n  border-radius: 50%;\n  background-color: white;\n  bottom: 40%;\n  left: 23%;\n  filter: drop-shadow(0px 0px 10px white);\n}\n\n.sun::after {\n  position: absolute;\n  content: \"\";\n  width: 118%;\n  height: 118%;\n  border-radius: 50%;\n  background-color: white;\n  opacity: 0.5;\n}\n\n.sun::before {\n  position: absolute;\n  content: \"\";\n  width: 134%;\n  height: 134%;\n  border-radius: 50%;\n  background-color: white;\n  opacity: 0.1;\n}\n\n.ocean {\n  overflow: hidden;\n  bottom: 0;\n  width: 100%;\n  height: 28%;\n  background: rgb(241, 192, 125);\n  background: linear-gradient(\n    0deg,\n    rgba(241, 192, 125, 1) 0%,\n    rgba(247, 218, 150, 1) 100%\n  );\n}\n\n.reflection {\n  position: absolute;\n  background-color: white;\n  opacity: 0.5;\n  z-index: 1;\n}\n\n.reflection:nth-child(1) {\n  width: 40px;\n  height: 10px;\n  clip-path: polygon(0% 0%, 100% 0%, 50% 20%);\n  top: 5%;\n  left: 32%;\n}\n\n.reflection:nth-child(2) {\n  width: 80px;\n  height: 15px;\n  clip-path: polygon(0% 0%, 100% 0%, 60% 20%, 40% 20%);\n  top: 15%;\n  left: 39%;\n}\n\n.reflection:nth-child(3) {\n  width: 60px;\n  height: 2px;\n  clip-path: polygon(0% 50%, 40% 0%, 60% 0%, 100% 50%, 60% 100%, 40% 100%);\n  top: 27%;\n  right: 15%;\n}\n\n.reflection:nth-child(4) {\n  width: 70px;\n  height: 2px;\n  clip-path: polygon(0% 50%, 40% 0%, 60% 0%, 100% 50%, 60% 100%, 40% 100%);\n  top: 37%;\n  right: 28%;\n}\n.reflection:nth-child(5) {\n  width: 70px;\n  height: 3px;\n  clip-path: polygon(0% 50%, 40% 0%, 60% 0%, 100% 50%, 60% 100%, 40% 100%);\n  top: 46%;\n  right: 8%;\n}\n\n.hill-1 {\n  right: -25%;\n  bottom: 20%;\n  width: 150px;\n  height: 40px;\n  border-radius: 50%;\n  background-color: #e6b29d;\n}\n\n.shadow-hill-1 {\n  right: -25%;\n  top: -30%;\n  width: 150px;\n  height: 40px;\n  border-radius: 50%;\n  background-color: #f1c7a0;\n  opacity: 1;\n}\n\n.hill-2 {\n  right: -36%;\n  bottom: 10%;\n  width: 150px;\n  height: 80px;\n  border-radius: 50%;\n  background-color: #c29182;\n}\n\n.shadow-hill-2 {\n  right: -36%;\n  top: -65%;\n  width: 150px;\n  height: 80px;\n  border-radius: 50%;\n  background-color: #e5bb96;\n  opacity: 1;\n}\n\n.hill-3 {\n  left: -100%;\n  bottom: -28%;\n  width: 350px;\n  height: 150px;\n  border-radius: 50%;\n  background-color: #b77873;\n  z-index: 3;\n}\n\n.tree-1 {\n  bottom: 20%;\n  left: 3%;\n  width: 50px;\n  height: 70px;\n  z-index: 3;\n}\n\n.tree-2 {\n  bottom: 14%;\n  left: 25%;\n  width: 50px;\n  height: 70px;\n  z-index: 3;\n}\n\n.hill-4 {\n  right: -100%;\n  bottom: -40%;\n  width: 350px;\n  height: 150px;\n  border-radius: 50%;\n  background-color: #a16773;\n  z-index: 3;\n}\n\n.tree-3 {\n  bottom: 10%;\n  right: 1%;\n  width: 65px;\n  height: 80px;\n  z-index: 3;\n}\n\n.filter {\n  height: 100%;\n  width: 100%;\n  background: linear-gradient(\n    0deg,\n    rgba(255, 255, 255, 1) 0%,\n    rgba(255, 255, 255, 0) 40%\n  );\n  z-index: 5;\n  opacity: 0.2;\n}\n\n/* Content section */\n.content-section {\n  width: 100%;\n  height: 30%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n\n.weather-info {\n  display: flex;\n  align-items: center;\n  justify-content: space-around;\n  position: absolute;\n  text-align: center;\n  top: 0;\n  right: 0%;\n  width: 100%;\n  padding-top: 15px;\n  color: white;\n  z-index: 10;\n}\n\n.weather-info .left-side:not(.icon) {\n  width: 20%;\n  font-size: 11pt;\n  font-weight: 600;\n  align-self: baseline;\n}\n\n.icon {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.icon svg {\n  width: 40px;\n}\n\n.weather-info .right-side {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-end;\n}\n\n.weather-info .right-side p:nth-child(2) {\n  font-size: 9pt;\n  margin: 0;\n  padding: 0;\n}\n\n.weather-info .location span {\n  font-size: 11pt;\n  font-weight: 700;\n  text-transform: uppercase;\n}\n\n.location {\n  display: flex;\n  align-items: center;\n  justify-content: flex-end;\n  width: 100%;\n  padding: 0;\n  margin: 0;\n}\n\n.location svg {\n  width: 14px;\n  height: auto;\n}\n\n.temperature {\n  font-size: 20pt;\n  font-weight: 700;\n  line-height: 30px;\n}\n\n.forecast {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: space-evenly;\n  height: 100%;\n  width: 100%;\n  padding: 10px 25px;\n}\n\n.forecast > div {\n  width: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  color: lightslategray;\n  font-size: 9pt;\n}\n\n.separator {\n  width: 100%;\n  height: 2px;\n  background-color: rgb(233, 233, 233);\n  border-radius: 1px;\n}\n"
