    "css": ".results-summary-container {\n  font-family: \"Hanken Grotesk\", sans-serif;\n  display: flex;\n  flex-direction: column;\n  width: 350px;\n  gap: 10px;\n  border-radius: 10px;\n  box-shadow: 10px 10px 30px rgba(120, 87, 255, 0.8);\n  backface-visibility: hidden;\n}\n\n.heading-primary,\n.heading-secondary,\n.heading-tertiary {\n  color: #ffffff;\n  text-transform: capitalize;\n  margin-bottom: 15px;\n  text-transform: uppercase;\n  letter-spacing: 1px;\n}\n\n.heading-primary {\n  font-size: 36px;\n  font-weight: 700;\n  background-image: linear-gradient(to right, #f7bb97, #dd5e89);\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n  transform: scale(1.4);\n}\n\n.heading-secondary {\n  font-size: 24px;\n  font-weight: 700;\n  margin-top: 15px;\n  letter-spacing: 1px;\n}\n\n.heading-secondary--blue {\n  color: hsl(224, 30%, 27%);\n}\n\n.heading-tertiary {\n  font-size: 20px;\n  font-weight: 500;\n  margin-bottom: 20px;\n  color: hsl(221, 100%, 96%);\n}\n\n.paragraph {\n  font-size: 17px;\n  line-height: 1.6;\n  color: hsl(221, 100%, 96%);\n}\n\n.paragraph-text-box {\n  width: 100%;\n}\n\n.text-center {\n  text-align: center;\n}\n\n.margin-1 {\n  margin-bottom: 10px;\n}\n\n.results-summary-container__result {\n  display: flex;\n  flex-direction: column;\n  text-align: center;\n  align-items: center;\n  justify-content: center;\n  padding: 20px 10px;\n  border-radius: 10px 10px 0 0;\n  background-image: linear-gradient(to bottom, #aa076b, #61045f);\n  .result-box {\n  width: 150px;\n  height: 150px;\n  border-radius: 50%;\n  background-image: linear-gradient(-45deg, #ef629f, #42275a);\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n}\n\n.result {\n  margin-top: -12px;\n  font-size: 14px;\n  font-weight: 400;\n  color: hsl(241, 100%, 89%);\n}\n}\n\n.results-summary-container__options {\n  padding: 0 16px;\n}\n\n.summary-result-options {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.result-option {\n  width: 100%;\n  height: 40px;\n  background-color: hsl(0, 100%, 97%);\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 10px;\n  border-radius: 3px;\n  cursor: pointer;\n}\n\n.result-option-memory {\n  background-color: hsl(39, 100%, 97%);\n}\n\n.result-option-verbal {\n  background-color: hsl(166, 100%, 97%);\n}\n\n.result-option-Visual {\n  background-color: hsl(234, 85%, 97%);\n}\n\n.icon-box {\n  display: flex;\n  font-size: 16px;\n  align-items: center;\n  gap: 2px;\n}\n\n.reaction-icon-text {\n  color: hsl(0, 100%, 67%);\n}\n\n.memory-icon-text {\n  color: hsl(39, 100%, 56%);\n}\n\n.verbal-icon-text {\n  color: hsl(166, 100%, 37%);\n}\n\n.visual-icon-text {\n  color: hsl(234, 85%, 45%);\n}\n\n.result-box {\n  font-size: 14px;\n  color: hsl(241, 100%, 89%);\n  font-weight: 700;\n}\n\n.result-box span {\n  font-size: 14px;\n  color: hsl(224, 30%, 27%);\n}\n\n.btn {\n  width: 100%;\n  padding: 10px;\n  color: #ffffff;\n  background-image: linear-gradient(to right, #aa076b, #61045f);\n  border: none;\n  border-radius: 3px;\n  font-size: 17px;\n  text-transform: uppercase;\n  letter-spacing: 2px;\n  font-weight: 500;\n  cursor: pointer;\n  margin: 15px 0 30px 0;\n  transition: all 0.3s;\n}\n\n.btn:hover {\n  transform: translateY(5px);\n  background-image: linear-gradient(to left, #aa076b, #61045f);\n}\n\n.icon {\n  cursor: pointer;\n  filter: grayscale(1);\n  transition: 0.3s linear;\n}\n\n.icon:hover {\n  filter: grayscale(0);\n}\n\n@keyframes background {\n  0% {\n    background-image: linear-gradient(to right, #aa076b, #61045f);\n  }\n\n  50% {\n    background-image: linear-gradient(to right, #aa076b, #61045f);\n  }\n\n  100% {\n    background-image: linear-gradient(to right, #ef629f, #42275a);\n  }\n}\n\n@keyframes gradient {\n  0% {\n    background-position: 0% 50%;\n    background-image: linear-gradient(-45deg, #ef629f, #42275a);\n  }\n\n  50% {\n    background-position: 100% 50%;\n    background-image: linear-gradient(to bottom, #aa076b, #61045f);\n  }\n\n  100% {\n    background-position: 0% 50%;\n    background-image: linear-gradient(to top, #ef629f, #42275a);\n  }\n}\n\n.confetti {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  position: absolute;\n  width: 360px;\n  height: 50%;\n  overflow: hidden;\n  z-index: 1000;\n}\n\n.confetti-piece {\n  position: absolute;\n  width: 10px;\n  height: 20px;\n  background-color: hsl(39, 100%, 56%);\n  top: 0;\n  opacity: 0;\n  animation: makeItRain 3000ms infinite ease-in-out;\n}\n\n.confetti-piece:nth-child(1) {\n  left: 7%;\n  transform: rotate(-10deg);\n  animation-delay: 182ms;\n  animation-duration: 2000ms;\n}\n\n.confetti-piece:nth-child(2) {\n  left: 14%;\n  transform: rotate(20deg);\n  animation-delay: 161ms;\n  animation-duration: 2076ms;\n}\n\n.confetti-piece:nth-child(3) {\n  left: 21%;\n  transform: rotate(-51deg);\n  animation-delay: 481ms;\n  animation-duration: 2103ms;\n}\n\n.confetti-piece:nth-child(4) {\n  left: 28%;\n  transform: rotate(61deg);\n  animation-delay: 334ms;\n  animation-duration: 1008ms;\n}\n\n.confetti-piece:nth-child(5) {\n  left: 35%;\n  transform: rotate(-52deg);\n  animation-delay: 302ms;\n  animation-duration: 1776ms;\n}\n\n.confetti-piece:nth-child(6) {\n  left: 42%;\n  transform: rotate(38deg);\n  animation-delay: 180ms;\n  animation-duration: 1168ms;\n}\n\n.confetti-piece:nth-child(7) {\n  left: 49%;\n  transform: rotate(11deg);\n  animation-delay: 395ms;\n  animation-duration: 1200ms;\n}\n\n.confetti-piece:nth-child(8) {\n  left: 56%;\n  transform: rotate(49deg);\n  animation-delay: 14ms;\n  animation-duration: 1887ms;\n}\n\n.confetti-piece:nth-child(9) {\n  left: 63%;\n  transform: rotate(-72deg);\n  animation-delay: 149ms;\n  animation-duration: 1805ms;\n}\n\n.confetti-piece:nth-child(10) {\n  left: 70%;\n  transform: rotate(10deg);\n  animation-delay: 351ms;\n  animation-duration: 2059ms;\n}\n\n.confetti-piece:nth-child(11) {\n  left: 77%;\n  transform: rotate(4deg);\n  animation-delay: 307ms;\n  animation-duration: 1132ms;\n}\n\n.confetti-piece:nth-child(12) {\n  left: 84%;\n  transform: rotate(42deg);\n  animation-delay: 464ms;\n  animation-duration: 1776ms;\n}\n\n.confetti-piece:nth-child(13) {\n  left: 91%;\n  transform: rotate(-72deg);\n  animation-delay: 429ms;\n  animation-duration: 1818ms;\n}\n\n.confetti-piece:nth-child(14) {\n  left: 94%;\n  transform: rotate(-72deg);\n  animation-delay: 429ms;\n  animation-duration: 818ms;\n}\n\n.confetti-piece:nth-child(15) {\n  left: 96%;\n  transform: rotate(-72deg);\n  animation-delay: 429ms;\n  animation-duration: 2818ms;\n}\n\n.confetti-piece:nth-child(16) {\n  left: 98%;\n  transform: rotate(-72deg);\n  animation-delay: 429ms;\n  animation-duration: 2818ms;\n}\n\n.confetti-piece:nth-child(17) {\n  left: 50%;\n  transform: rotate(-72deg);\n  animation-delay: 429ms;\n  animation-duration: 2818ms;\n}\n\n.confetti-piece:nth-child(18) {\n  left: 60%;\n  transform: rotate(-72deg);\n  animation-delay: 429ms;\n  animation-duration: 1818ms;\n}\n\n.confetti-piece:nth-child(odd) {\n  background-color: hsl(0, 100%, 67%);\n}\n\n.confetti-piece:nth-child(even) {\n  z-index: 1;\n}\n\n.confetti-piece:nth-child(4n) {\n  width: 6px;\n  height: 14px;\n  animation-duration: 4000ms;\n  background-color: #c33764;\n}\n\n.confetti-piece:nth-child(5n) {\n  width: 3px;\n  height: 10px;\n  animation-duration: 4000ms;\n  background-color: #b06ab3;\n}\n\n.confetti-piece:nth-child(3n) {\n  width: 4px;\n  height: 12px;\n  animation-duration: 2500ms;\n  animation-delay: 3000ms;\n  background-color: #dd2476;\n}\n\n.confetti-piece:nth-child(3n-7) {\n  background-color: hsl(166, 100%, 37%);\n}\n\n@keyframes makeItRain {\n  from {\n    opacity: 0;\n  }\n\n  50% {\n    opacity: 1;\n  }\n\n  to {\n    transform: translateY(200px);\n  }\n}\n\n"
