    "css": ".card {\n  --main-color: #fff;\n  --bg-color: #323232;\n  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;\n  position: relative;\n  padding: 20px;\n  width: 320px;\n  background: var(--bg-color);\n  border-radius: 20px;\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n\n.card__wrapper {\n  display: flex;\n  flex-direction: row;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.card__back svg, .card__menu svg {\n  width: 20px;\n  height: 20px;\n}\n\n.card__img {\n  width: 170px;\n  height: 170px;\n  background: linear-gradient(90deg, #fff8f79a, #f0f7dfa2);\n  border-radius: 100%;\n  margin-inline: auto;\n}\n\n.card__img svg {\n  height: 150px;\n  transform: rotate(-45deg) translate(15px, 0px);\n}\n\n.card__title {\n  font-weight: 600;\n  font-size: 25px;\n  color: var(--main-color);\n}\n\n.card__subtitle {\n  font-weight: 400;\n  font-size: 15px;\n  color: var(--main-color);\n  letter-spacing: 0.5px;\n}\n\n.card__price {\n  font-weight: 600;\n  font-size: 22px;\n  color: var(--main-color);\n}\n\n.card__counter {\n  display: flex;\n  flex-direction: row;\n  align-items: center;\n  gap: 15px;\n  padding: 5px;\n  background: #666;\n  border-radius: 50px;\n}\n\n.card__counter-score, .card__btn {\n  font-weight: 600;\n  font-size: 22px;\n  color: var(--main-color);\n}\n\n.card__btn {\n  width: 30px;\n  height: 30px;\n  border-radius: 100%;\n  border: none;\n  background: transparent;\n}\n\n.card__btn-plus {\n  background: var(--bg-color);\n}"
