    "css": ".warning {\n  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;\n  width: 320px;\n  padding: 12px;\n  display: flex;\n  flex-direction: row;\n  align-items: center;\n  justify-content: start;\n  background: #FEF7D1;\n  border-radius: 8px;\n  box-shadow: 0px 0px 5px -3px #111;\n}\n\n.warning__icon {\n  width: 20px;\n  height: 20px;\n  transform: translateY(-2px);\n  margin-right: 8px;\n}\n\n.warning__icon path {\n  fill: #F7C752;\n}\n\n.warning__title {\n  font-weight: 500;\n  font-size: 14px;\n  color: #755118;\n}\n\n.warning__close {\n  width: 20px;\n  height: 20px;\n  margin-left: auto;\n  cursor: pointer;\n}\n\n.warning__close path {\n  fill: #755118;\n}"
