    "css": ".main {\n  --clr: #FDFFFC;\n  --clr-text: #1C1D21;\n  --clr1: #018E42;\n  background-color: var(--clr);\n  padding: 1em;\n  padding-bottom: 1.1em;\n  border-radius: 15px;\n  margin: 1em;\n  display: flex;\n  flex-direction: column;\n  outline: 2px solid var(--clr);\n  outline-offset: 3px;\n}\n\n/* new start */\n.top-bar {\n  display: flex;\n  align-items: center;\n  align-self: flex-end;\n  gap: .5rem;\n  list-style: none;\n}\n\n.btn {\n  fill: var(--clr);\n  border: none;\n  width: 2rem;\n  aspect-ratio: 1/1;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  z-index: 10;\n  border-radius: 50%;\n}\n\n.close {\n  background-color: orangered;\n}\n\n.minimize {\n  background-color: var(--clr1);\n}\n\n.songs {\n  display: flex;\n  flex-direction: column;\n  gap: .5rem;\n}\n/* new end */\n\n.loader {\n  display: flex;\n  flex-direction: row;\n  height: 4em;\n  padding-inline: 1em;\n  transform: rotate(180deg);\n  justify-content: right;\n  border-radius: 10px;\n  transition: .4s ease-in-out;\n}\n\n.song > * {\n  transition: .4s ease-in-out;\n}\n\n.loader:hover {\n  cursor: pointer;\n  background-color: var(--clr1);\n  --clr-text: #FDFFFC;\n}\n\n.currentplaying {\n  display: flex;\n  align-items: center;\n  align-self: center;\n  margin: 1em 2rem;\n  padding: .5rem;\n  width: 100%;\n  background-color: #018E42dd;\n  border-radius: .5rem;\n}\n\n.spotify {\n  width: 50px;\n  height: 50px;\n  margin-right: 0.6em;\n}\n\n.heading {\n  color: var(--clr);\n  font-size: 1.1em;\n  font-weight: bold;\n  align-self: center;\n}\n\n.loading {\n  display: flex;\n  margin-top: 1em;\n  margin-left: 0.3em;\n}\n\n.load {\n  width: 2px;\n  height: 33px;\n  background-color: limegreen;\n  animation: 1s move6 infinite;\n  border-radius: 5px;\n  margin: 0.1em;\n}\n\n.load:nth-child(1) {\n  animation-delay: 0.2s;\n}\n\n.load:nth-child(2) {\n  animation-delay: 0.4s;\n}\n\n.load:nth-child(3) {\n  animation-delay: 0.6s;\n}\n\n.play {\n  position: relative;\n  left: 0.35em;\n  height: 1.6em;\n  width: 1.6em;\n  clip-path: polygon(50% 50%, 100% 50%, 75% 6.6%);\n  background-color: var(--clr-text);\n  transform: rotate(-90deg);\n  align-self: center;\n  margin-top: 0.7em;\n  justify-self: center;\n  transition: .4s ease-in-out;\n}\n\n.albumcover {\n  position: relative;\n  margin-right: 1em;\n  height: 40px;\n  width: 40px;\n  background-color: rgb(233, 232, 232);\n  align-self: center;\n  border-radius: 5px;\n}\n\n.song {\n  position: relative;\n  transform: rotate(180deg);\n  margin-right: 1em;\n  color: var(--clr-text);\n  align-self: center;\n}\n\n.artist {\n  font-size: 0.6em;\n  color: var(--clr-text);\n}\n\n@keyframes move6 {\n  0% {\n    height: 0.2em;\n  }\n\n  25% {\n    height: 0.7em;\n  }\n\n  50% {\n    height: 1.5em;\n  }\n\n  100% {\n    height: 0.2em;\n  }\n}"
