    "css": ".card {\n  position: relative;\n  width: 190px;\n  height: 254px;\n  color: #fff;\n  transition: 0.5s;\n  cursor: pointer;\n  transform: rotateX(-55deg) rotateY(15deg) rotateZ(60deg);\n}\n\n.card:hover {\n  transform: rotate(0);\n}\n\n.card:active {\n  transform: translateY(-20px) rotate(-3deg);\n  scale: 0.95;\n}\n\n.card::before {\n  content: '';\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  top: 0;\n  left: 0;\n  background: linear-gradient(315deg, #03a9f4, #ff0058);\n}\n\n.card::after {\n  content: '';\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  background: linear-gradient(315deg, #03a9f4, #ff0058);\n  filter: blur(30px);\n}\n\n.card span {\n  position: absolute;\n  top: 6px;\n  left: 6px;\n  right: 6px;\n  bottom: 6px;\n  background-color: rgba(0, 0, 0, 0.6);\n  z-index: 2;\n}\n\n.card span::before {\n  content: '';\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 50%;\n  height: 100%;\n  background-color: rgba(255, 255, 255, 0.1);\n}\n\n.card .content {\n  position: relative;\n  padding: 10px;\n  z-index: 10;\n  width: 100%;\n  height: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-weight: 800;\n  font-size: 1.5em;\n}"
