    "css": ".login-card {\n  width: 250px;\n  height: 240px;\n  background-color: #f2f2f2;\n  border-radius: 25px;\n  box-shadow: 2px 2px 15px rgb(193, 193, 193);\n}\n\n.instruction-text {\n  color: rgb(150, 150, 150);\n  text-align: center;\n  font-size: 12px;\n  margin-top: 10px;\n  margin-bottom: px;\n}\n\n.login-card button {\n  cursor: pointer;\n}\n\n.normal-signin {\n  padding: 10px;\n  font-size: 17px;\n  width: 70%;\n  margin-top: 25px;\n  margin-left: 37px;\n  border: 2px solid transparent;\n  border-radius: 5em;\n  background-color: #1b77da;\n  color: #f2f2f2;\n  font-weight: bold;\n  font-family: sans-serif;\n  transition: 0.2s;\n}\n\n.normal-signin:hover {\n  background-color: transparent;\n  color: #1b77da;\n  border: 2px solid #1b77da;\n}\n\n.create-account {\n  padding: 10px;\n  font-size: 17px;\n  width: 70%;\n  margin-top: 5px;\n  margin-left: 37px;\n  margin-bottom: 5px;\n  border: 2px solid transparent;\n  border-radius: 5em;\n  background-color: #e8e8e8;\n  color: #1b77da;\n  font-weight: bold;\n  font-family: sans-serif;\n  transition: 0.2s;\n}\n\n.create-account:hover {\n  background-color: transparent;\n  color: #1b77da;\n  border: 2px solid #1b77da;\n}\n\n.alternate-login {\n  margin-left: 42px;\n  margin-top: 5px;\n  background-color: #f2f2f2;\n  border-radius: 5em;\n}\n\n.m-sign {\n  padding: 7px;\n  font-size: 14px;\n  height: 40px;\n  width: 40px;\n  border-radius: 5em;\n  margin-top: 5px;\n  background-color: #7FBA00;\n  border: 2px solid transparent;\n  transition: 0.2s;\n}\n\n.m-sign svg {\n  width: 27px;\n  height: 27px;\n  margin-top: -2px;\n  margin-left: -2px;\n  fill: #f2f2f2;\n}\n\n.m-sign:hover {\n  background-color: transparent;\n  border: 2px solid #7FBA00;\n}\n\n.m-sign:hover svg {\n  fill: #7FBA00;\n}\n\n.g-sign {\n  padding: 7px;\n  font-size: 14px;\n  height: 40px;\n  width: 40px;\n  border-radius: 5em;\n  margin-top: 5px;\n  margin-left: 15px;\n  background-color: #DB4437;\n  border: 2px solid transparent;\n  transition: 0.2s;\n}\n\n.g-sign svg {\n  width: 23px;\n  height: 25px;\n  margin-top: -1.5px;\n  fill: #f2f2f2;\n}\n\n.g-sign:hover {\n  background-color: transparent;\n  border: 2px solid #DB4437;\n}\n\n.g-sign:hover svg {\n  fill: #DB4437;\n}\n\n.a-sign {\n  padding: 7px;\n  font-size: 14px;\n  height: 40px;\n  width: 40px;\n  border-radius: 5em;\n  margin-top: 5px;\n  margin-left: 15px;\n  background-color: #000000;\n  border: 2px solid transparent;\n  transition: 0.2s;\n}\n\n.a-sign svg {\n  width: 25px;\n  height: 25px;\n  margin-top: -1px;\n  margin-left: -1px;\n  fill: #f2f2f2;\n}\n\n.a-sign:hover {\n  background-color: transparent;\n  border: 2px solid #000000;\n}\n\n.a-sign:hover svg {\n  fill: #000000;\n}"
