    "css": ".container {\n  background-color: #fff7e6;\n  display: flex;\n  width: 250px;\n  height: 75px;\n  position: relative;\n  border-radius: 5px;\n  transition: 0.3s ease-in-out;\n  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);\n}\n\n.container:hover {\n  transform: scale(1.03);\n  width: 150px;\n}\n\n.container:hover .left-side {\n  width: 100%;\n}\n\n.left-side {\n  background: linear-gradient(135deg, #ff8c00, #ff4d4d);\n  width: 85px;\n  height: 75px;\n  border-radius: 4px 0 0 4px;\n  position: relative;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  cursor: pointer;\n  transition: 0.3s;\n  flex-shrink: 0;\n  overflow: hidden;\n}\n\n.right-side {\n  width: calc(100% - 85px);\n  display: flex;\n  align-items: center;\n  overflow: hidden;\n  cursor: pointer;\n  justify-content: space-between;\n  white-space: nowrap;\n  transition: 0.3s;\n}\n\n.right-side:hover {\n  background-color: #ffecd1;\n}\n\n.arrow {\n  width: 14px;\n  height: 14px;\n  margin-right: 12px;\n}\n\n.new {\n  font-size: 15px;\n  font-family: \"Inter\", sans-serif;\n  margin-left: 12px;\n  color: #333;\n}\n\n.card {\n  width: 48px;\n  height: 30px;\n  background-color: #ffb366;\n  border-radius: 4px;\n  position: absolute;\n  display: flex;\n  z-index: 10;\n  flex-direction: column;\n  align-items: center;\n  box-shadow: 5px 5px 5px -2px rgba(255, 77, 77, 0.4);\n}\n\n.card-line {\n  width: 42px;\n  height: 8px;\n  background-color: #ffcc99;\n  border-radius: 1px;\n  margin-top: 4px;\n}\n\n@media only screen and (max-width: 480px) {\n  .container {\n    transform: scale(0.6);\n  }\n\n  .container:hover {\n    transform: scale(0.63);\n  }\n\n  .new {\n    font-size: 13px;\n  }\n}\n\n.buttons {\n  width: 5px;\n  height: 5px;\n  background-color: #cc4b00;\n  box-shadow:\n    0 -6px 0 0 #992d00,\n    0 6px 0 0 #ff6a1a;\n  border-radius: 50%;\n  margin-top: 3px;\n  transform: rotate(90deg);\n  margin: 6px 0 0 -18px;\n}\n\n.container:hover .card {\n  animation: slide-top 0.9s cubic-bezier(0.68, -0.55, 0.265, 1.55) both;\n}\n\n.container:hover .post {\n  animation: slide-post 0.7s cubic-bezier(0.23, 1, 0.32, 1) both;\n}\n\n@keyframes slide-top {\n  0% {\n    transform: translateY(0);\n  }\n  50% {\n    transform: translateY(-45px) rotate(90deg);\n  }\n  60% {\n    transform: translateY(-45px) rotate(90deg);\n  }\n  100% {\n    transform: translateY(-5px) rotate(90deg);\n  }\n}\n\n.post {\n  width: 42px;\n  height: 50px;\n  background-color: #f5f5f5;\n  position: absolute;\n  z-index: 11;\n  bottom: 6px;\n  top: 75px;\n  border-radius: 4px;\n  overflow: hidden;\n}\n\n.post-line {\n  width: 32px;\n  height: 5px;\n  background-color: #666;\n  position: absolute;\n  border-radius: 0 0 2px 2px;\n  right: 5px;\n  top: 5px;\n}\n\n.post-line:before {\n  content: \"\";\n  position: absolute;\n  width: 32px;\n  height: 5px;\n  background-color: #888;\n  top: -5px;\n}\n\n.screen {\n  width: 32px;\n  height: 15px;\n  background-color: #ffffff;\n  position: absolute;\n  top: 14px;\n  right: 5px;\n  border-radius: 2px;\n}\n\n.numbers {\n  width: 7px;\n  height: 7px;\n  background-color: #999;\n  box-shadow:\n    0 -11px 0 0 #999,\n    0 11px 0 0 #999;\n  border-radius: 1px;\n  position: absolute;\n  transform: rotate(90deg);\n  left: 17px;\n  top: 34px;\n}\n\n.numbers-line2 {\n  width: 7px;\n  height: 7px;\n  background-color: #bbb;\n  box-shadow:\n    0 -11px 0 0 #bbb,\n    0 11px 0 0 #bbb;\n  border-radius: 1px;\n  position: absolute;\n  transform: rotate(90deg);\n  left: 17px;\n  top: 45px;\n}\n\n@keyframes slide-post {\n  50% {\n    transform: translateY(0);\n  }\n  100% {\n    transform: translateY(-45px);\n  }\n}\n\n.icon {\n  position: absolute;\n  font-size: 11px;\n  font-family: \"Inter\", sans-serif;\n  width: 100%;\n  left: 0;\n  top: 0;\n  color: #d32f2f;\n  text-align: center;\n}\n\n.container:hover .icon {\n  animation: fade-in-fwd 0.3s 0.7s backwards;\n}\n\n@keyframes fade-in-fwd {\n  0% {\n    opacity: 0;\n    transform: translateY(-3px);\n  }\n  100% {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n"
