    "css": ".card {\n  background-color: #25241c;\n  border: 3px solid #f7df1e;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  font-size: 26px;\n  font-weight: 700;\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;\n  padding: 30px 40px;\n  color: #f7df1e;\n  border-radius: 45px;\n}\n\n.App-logo {\n  pointer-events: none;\n  width: 120px;\n  margin-bottom: 20px;\n}\n\n.App-button {\n  padding: 10px 20px;\n  background-color: transparent;\n  color: #f7df1e;\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;\n  font-size: 15px;\n  border: 3px solid #f7df1e;\n  border-radius: 5em;\n  margin-top: 20px;\n  transition: 0.2s;\n}\n\n.App-button:hover {\n  color: #2e2d23;\n  background-color: #f7df1e;\n}"
