    "css": ".card {\n  width: 190px;\n  height: 254px;\n  color: white;\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  grid-template-rows: 1fr 1fr;\n  gap: 5px;\n  overflow: visible;\n}\n\n.card .item {\n  border-radius: 10px;\n  width: 100%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n}\n\n.item:hover {\n  transform: scale(1.95);\n  transition: all 1s ease-in-out;\n  rotate: 360deg;\n}\n\n.item svg {\n  width: 40px;\n  height: 40px;\n  margin-bottom: 7px;\n}\n\n.item--1 {\n  background: #c7c7ff;\n}\n\n.item--2 {\n  background: #ffd8be;\n}\n\n.item--3 {\n  background: #a9ecbf;\n}\n\n.item--4 {\n  background: #f3bbe1;\n}\n\n.quantity {\n  font-size: 25px;\n  font-weight: 600;\n}\n\n.text {\n  font-size: 12px;\n  font-family: inherit;\n  font-weight: 600;\n}\n\n.text--1 {\n  color: rgba(149,149,255,1);\n}\n\n.text--2 {\n  color: rgba(252,161,71,1);\n}\n\n.text--3 {\n  color: rgba(66,193,110,1);\n}\n\n.text--4 {\n  color: rgba(220,91,183,1);\n}"
