    "css": ".card {\n  width: 190px;\n  height: 254px;\n  position: relative;\n  border-radius: 16px;\n  background: #f5f5f5;\n  transition: box-shadow .3s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n  overflow: hidden;\n  cursor: pointer;\n}\n\n.card-img {\n  position: absolute;\n  height: 100%;\n  width: 100%;\n  background-color: #6eee87;\n}\n\n.card-info {\n  position: absolute;\n  width: 100%;\n  bottom: 0;\n  padding: 1rem;\n  display: flex;\n  align-items: flex-end;\n  justify-content: space-between;\n}\n\n.card-icon {\n  opacity: 0;\n  transform: translateX(-20%);\n  width: 2em;\n  height: 2em;\n  transition: all .3s ease-in-out;\n}\n\n.icon {\n  --size: 20px;\n  width: var(--size);\n  height: var(--size);\n}\n\n/*Text*/\n.card-text p {\n  line-height: 140%;\n /*Delete this line for multi-line text*/\n  white-space: nowrap;\n}\n\n.text-title {\n  font-weight: 900;\n  font-size: 1.2rem;\n  color: #222;\n}\n\n.text-subtitle {\n  color: #333;\n  font-weight: 500;\n  font-size: 1rem;\n}\n\n/*Hover*/\n.card:hover {\n  box-shadow: 0 10px 20px 4px rgba(35, 35, 35, .1);\n}\n\n.card:hover .card-icon {\n  opacity: 1;\n  transform: translateX(20%);\n}"
