    "css": "/* CodePen Card */\n\n.card {\n  width: 15em;\n  height: 10em;\n  background-color: #252525;\n  border-radius: 7px;\n  cursor: pointer;\n}\n\n.fl {\n  display: flex;\n  justify-content: flex-end;\n  opacity: 0;\n  transition: .2s ease-in-out;\n}\n\n.fl:hover .fullscreen {\n  scale: 1.2;\n}\n\n.fl:hover .fullscreen_svg {\n  fill: white;\n}\n\n.fullscreen {\n  width: 1.5em;\n  height: 1.5em;\n  border-radius: 5px;\n  background-color: #727890;\n  margin: 1em;\n  margin-right: 0.5em;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: .2s ease-in-out;\n  box-shadow: 2px 2px 6px rgba(0,0,0,.4);\n}\n\n.fullscreen_svg {\n  width: 15px;\n  height: 15px;\n  fill: rgb(177, 176, 176);\n  transition: .2s ease-in-out;\n}\n\n.card_back {\n  position: absolute;\n  width: 15em;\n  height: 13em;\n  background-color: rgba(30, 31, 38, 0.575);\n  border-radius: 7px;\n  margin-top: -5em;\n  margin-left: 0.7em;\n  transition: .2s ease-in-out;\n  z-index: -1;\n}\n\n.main:hover .card_back {\n  margin-top: -6.25em;\n  margin-left: 0em;\n  scale: 1.1;\n  height: 15.25em;\n  cursor: pointer;\n}\n\n.main:hover .fl {\n  opacity: 1;\n  cursor: pointer;\n  margin-right: 0.5em;\n}\n\n.data {\n  display: flex;\n  flex-direction: row;\n  margin-top: 1em;\n}\n\n.img {\n  width: 2.25em;\n  height: 2.25em;\n  background-color: #252525;\n  border-radius: 5px;\n  overflow: hidden;\n}\n\n.text {\n  display: flex;\n  justify-content: center;\n  flex-direction: column;\n  margin-left: 0.5em;\n  font-family: Montserrat;\n  color: white;\n}\n\n.text_m {\n  font-weight: bold;\n  font-size: 0.9em;\n}\n\n.text_s {\n  font-size: 0.7em;\n}\n\n.btns {\n  display: flex;\n  gap: 0.5em;\n  transition: .2s ease-in-out;\n}\n\n.likes {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 2.5em;\n  height: 1.4em;\n  border-radius: 4px;\n  margin-top: -0.5em;\n  opacity: 0;\n  background-color: #444857;\n  transition: .2s ease-in-out;\n}\n\n.likes_text {\n  font-family: Montserrat;\n  font-size: 0.8em;\n  margin-left: 0.25em;\n  color: white;\n}\n\n.likes_svg {\n  width: 12px;\n  height: 12px;\n  fill: white;\n}\n\n.likes:hover {\n  background-color: #5A5F73;\n  cursor: pointer;\n}\n\n.comments {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 2.5em;\n  height: 1.4em;\n  border-radius: 4px;\n  margin-top: -0.5em;\n  opacity: 0;\n  background-color: #444857;\n  transition: .24s ease-in-out;\n}\n\n.comments_text {\n  font-family: Montserrat;\n  font-size: 0.8em;\n  margin-left: 0.25em;\n  color: white;\n}\n\n.comments_svg {\n  width: 12px;\n  height: 12px;\n  fill: white;\n}\n\n.comments:hover {\n  background-color: #5A5F73;\n  cursor: pointer;\n}\n\n.views {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 3em;\n  height: 1.4em;\n  border-radius: 4px;\n  margin-top: -0.5em;\n  opacity: 0;\n  background-color: #444857;\n  transition: .28s ease-in-out;\n}\n\n.views_text {\n  font-family: Montserrat;\n  font-size: 0.8em;\n  margin-left: 0.25em;\n  color: white;\n}\n\n.views_svg {\n  width: 12px;\n  height: 12px;\n  fill: white;\n}\n\n.views:hover {\n  background-color: #5A5F73;\n  cursor: pointer;\n}\n\n.main:hover .likes {\n  margin-top: 0.5em;\n  opacity: 1;\n}\n\n.main:hover .comments {\n  margin-top: 0.5em;\n  opacity: 1;\n}\n\n.main:hover .views {\n  margin-top: 0.5em;\n  opacity: 1;\n}\n\n\n\n/* The Main Switch */\n\n.card_content {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n/* The switch - the box around the slider */\n.switch_738 {\n  font-size: 13px;\n  position: relative;\n  display: inline-block;\n  width: 1.2em;\n  height: 3.3em;\n}\n\n/* Hide default HTML checkbox */\n.switch_738 .chk_738 {\n  opacity: 0;\n  width: 0;\n  height: 0;\n}\n\n/* The slider */\n.slider_738 {\n  position: absolute;\n  cursor: pointer;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background-color: #ccc;\n  transition: .4s;\n  border-radius: 5px;\n}\n\n.slider_738:before {\n  position: absolute;\n  content: \"\";\n  height: .5em;\n  width: 2.4em;\n  border-radius: 5px;\n  left: -0.6em;\n  top: 0.2em;\n  background-color: white;\n  box-shadow: 0 6px 7px rgba(0,0,0,0.3);\n  transition: .4s;\n}\n\n.slider_738:before, .slider_738:after {\n  content: \"\";\n  display: block;\n}\n\n.slider_738:after {\n  background: linear-gradient(transparent 50%, rgba(255, 255, 255, 0.15) 0) 0 50% / 50% 100%,\n\t\trepeating-linear-gradient(90deg,rgb(255, 255, 255) 0,rgb(255, 255, 255),rgb(255, 255, 255) 20%,rgb(255, 255, 255) 20%,rgb(255, 255, 255) 40%) 0 50% / 50% 100%,\n\t\tradial-gradient(circle at 50% 50%,rgb(255, 255, 255) 25%, transparent 26%);\n  background-repeat: no-repeat;\n  border: 0.25em solid transparent;\n  border-left: 0.4em solid #ffffff;\n  border-right: 0 solid transparent;\n  transition: border-left-color 0.1s 0.3s ease-out, transform 0.3s ease-out;\n  transform: translateX(-22.5%) rotate(90deg);\n  transform-origin: 25% 50%;\n  position: relative;\n  top: 0.5em;\n  left: 0.55em;\n  width: 2em;\n  height: 1em;\n  box-sizing: border-box;\n}\n\n.chk_738:checked + .slider_738 {\n  background-color: limegreen;\n}\n\n.chk_738:focus + .slider_738 {\n  box-shadow: 0 0 1px limegreen;\n}\n\n.chk_738:checked + .slider_738:before {\n  transform: translateY(2.3em);\n}\n\n.chk_738:checked + .slider_738:after {\n  transform: rotateZ(90deg) rotateY(180deg) translateY(0.45em) translateX(-1.4em);\n}"
