    "css": ".container {\n  width: 190px;\n  height: 254px;\n  background: transparent;\n  position: relative;\n  box-shadow: 0px 0px 5px rgba(0, 0, 0, 0.438);\n  overflow: hidden;\n  border-radius: 10px;\n}\n\n.card {\n  cursor: default;\n  width: 100%;\n  height: 100%;\n  position: relative;\n  z-index: 2;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 34px;\n  text-transform: uppercase;\n  letter-spacing: 2px;\n  color: #212121;\n  background-color: rgba(255, 255, 255, 0.074);\n  border: 1px solid rgba(255, 255, 255, 0.222);\n  -webkit-backdrop-filter: blur(20px);\n  backdrop-filter: blur(20px);\n  border-radius: 10px;\n  transition: all ease .3s;\n}\n\n.container::after,\n.container::before {\n  width: 100px;\n  height: 100px;\n  content: '';\n  position: absolute;\n  border-radius: 50%;\n  transition: .5s linear;\n}\n\n.container::after {\n  top: -20px;\n  left: -20px;\n  background-color: rgba(125, 214, 66, 0.603);\n  animation: animFirst 5s linear infinite;\n}\n\n.container::before {\n  background-color: rgb(226, 223, 54);\n  top: 70%;\n  left: 70%;\n  animation: animSecond 5s linear infinite;\n  animation-delay: 3s;\n}\n\n.container:hover {\n  box-shadow: 0px 0px 10px rgba(0, 77, 32, 0.432)\n}\n\n.container:hover::after {\n  left: 80px;\n  transform: scale(1.2);\n}\n\n.container:hover::before {\n  left: -10px;\n  transform: scale(1.2);\n}"
