    "css": ".card {\n  display: flex;\n  height: 70px;\n  width: 270px;\n}\n\n.card svg {\n  position: absolute;\n  display: flex;\n  width: 60%;\n  height: 100%;\n  font-size: 24px;\n  font-weight: 700;\n  opacity: 1;\n  transition: opacity 0.25s;\n  z-index: 2;\n  cursor: pointer;\n}\n\n.card .social-link1,.card .social-link2,.card .social-link3,.card .social-link4 {\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 25%;\n  color: whitesmoke;\n  font-size: 24px;\n  text-decoration: none;\n  transition: 0.25s;\n  border-radius: 50px;\n}\n\n.card svg {\n  transform: scale(1);\n}\n\n.card .social-link1:hover {\n  background-color: #1a1e22;\n  animation: bounce_613 0.4s linear;\n}\n\n.card .social-link2:hover {\n  background-color: #0a66c2;\n  animation: bounce_613 0.4s linear;\n}\n\n.card .social-link3:hover {\n  background-color: #0059f7;\n  animation: bounce_613 0.4s linear;\n}\n\n.card .social-link4:hover {\n  background-color: #1d4292;\n  animation: bounce_613 0.4s linear;\n}\n\n@keyframes bounce_613 {\n  40% {\n    transform: scale(1.4);\n  }\n\n  60% {\n    transform: scale(0.8);\n  }\n\n  80% {\n    transform: scale(1.2);\n  }\n\n  100% {\n    transform: scale(1);\n  }\n}"
