    "css": "/* RIP Uiverse points, welcome Creator points! */\n\n.card-id567 {\n  width: 190px;\n  height: 190px;\n  background: rgb(255, 255, 255);\n  border-radius: 1rem;\n  padding: 1rem;\n  position: relative;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  transition: 300ms ease;\n  animation: 8s thumb-thumb infinite;\n}\n\n.card-id567 svg path {\n  transition: 300ms ease;\n  stroke: rgb(20, 20, 20);\n  opacity: 0;\n}\n\n.bold-567 {\n  font-weight: bold;\n}\n\n.blurry-splash {\n  position: absolute;\n  inset: 0;\n  width: 60px;\n  margin: 0 auto;\n  height: 60px;\n  border-radius: 1rem;\n  z-index: -1;\n  opacity: 70%;\n  filter: blur(15px);\n  background: linear-gradient(\n    120deg, rgb(119, 0, 255)\n    , rgb(22, 94, 250), rgb(44, 226, 250));\n}\n\n.prompt-id567 {\n  position: absolute;\n  color: rgb(29, 29, 29);\n  text-align: center;\n}\n\n.really-small-text {\n  text-align: center;\n  width: 100%;\n  position: absolute;\n  font-size: 8px;\n  margin-top: 28px;\n  opacity: 0.5;\n}\n\n.card-id567:hover {\n  cursor: none;\n}\n\n.card-id567:hover .prompt-id567 {\n  transition: 300ms ease;\n  opacity: 0;\n}\n\n.token-container {\n  animation: 2s spinny-token-yayyy infinite;\n  margin-bottom: 10px;\n}\n\n.prompt-id567 svg path {\n  stroke: none;\n  opacity: 1;\n}\n\n.card-id567:hover svg path {\n  opacity: 1;\n}\n\n@keyframes spinny-token-yayyy {\n  0% {\n    transform: perspective(200px) rotateY(0deg);\n  }\n\n  100% {\n    transform: perspective(200px) rotateY(360deg);\n  }\n}\n\n@keyframes thumb-thumb {\n  0%, 10%, 100% {\n    transform: scale(100%);\n  }\n\n  5% {\n    transform: scale(103%);\n  }\n\n  7% {\n    transform: scale(97%);\n  }\n}"
