    "css": ".card {\n  --main-color: #fff;\n  --submain-color: #ccc;\n  --bg-color: #000;\n  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;\n  position: relative;\n  width: 300px;\n  height: 384px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  border-radius: 20px;\n  background: var(--bg-color);\n}\n\n.card__img {\n  height: 192px;\n  width: 100%;\n}\n\n.card__img svg {\n  height: 100%;\n  border-radius: 20px 20px 0 0;\n}\n\n.card__avatar {\n  position: absolute;\n  width: 114px;\n  height: 114px;\n  background: var(--bg-color);\n  border-radius: 100%;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  top: calc(50% - 57px);\n}\n\n.card__avatar svg {\n  width: 100px;\n  height: 100px;\n}\n\n.card__title {\n  margin-top: 60px;\n  font-weight: 500;\n  font-size: 18px;\n  color: var(--main-color);\n}\n\n.card__subtitle {\n  margin-top: 10px;\n  font-weight: 400;\n  font-size: 15px;\n  color: var(--submain-color);\n}\n\n.card__btn {\n  margin-top: 15px;\n  width: 76px;\n  height: 31px;\n  border: 2px solid var(--main-color);\n  border-radius: 4px;\n  font-weight: 700;\n  font-size: 11px;\n  color: var(--main-color);\n  background: var(--bg-color);\n  text-transform: uppercase;\n  transition: all 0.3s;\n}\n\n.card__btn-solid {\n  background: var(--main-color);\n  color: var(--bg-color);\n}\n\n.card__btn:hover {\n  background: var(--main-color);\n  color: var(--bg-color);\n}\n\n.card__btn-solid:hover {\n  background: var(--bg-color);\n  color: var(--main-color);\n}"
