    "css": ".card {\n  --main-color: #fff;\n  --bg-color: #090909;\n  --sub-main-color: #B9B9B9;\n  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;\n  width: 360px;\n  height: 478px;\n  background: var(--bg-color);\n  border-radius: 20px;\n  padding: 30px;\n}\n\n.card__menu {\n  cursor: pointer;\n}\n\n.card__img {\n  height: 224px;\n  width: 224px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  margin-inline: auto;\n  background: #131313;\n  border-radius: 100%;\n}\n\n.card__img svg {\n  width: 154px;\n  height: 154px;\n  border-radius: 100%;\n}\n\n.card__title {\n  font-weight: 500;\n  font-size: 28px;\n  color: var(--main-color);\n  text-align: center;\n  margin-bottom: 10px;\n}\n\n.card__subtitle {\n  font-weight: 400;\n  font-size: 16px;\n  color: var(--sub-main-color);\n  text-align: center;\n  cursor: pointer;\n}\n\n.card__wrapper {\n  display: flex;\n  flex-direction: row;\n  justify-content: space-between;\n  align-items: center;\n  gap: 10px;\n  margin-top: 20px;\n}\n\n.card__time {\n  font-weight: 400;\n  font-size: 12px;\n  color: var(--main-color);\n}\n\n.card__timeline {\n  width: 100%;\n  height: 4px;\n  display: flex;\n  align-items: center;\n  cursor: pointer;\n}\n\n.card__timeline progress {\n  width: 100%;\n  height: 100%;\n  border-radius: 100px;\n}\n\n.card__timeline progress::-webkit-progress-bar {\n  background-color: #424242;\n  border-radius: 100px;\n}\n\n.card__timeline progress::-webkit-progress-value {\n  background-color: #fff;\n  border-radius: 100px;\n}\n\n.card__btn {\n  border: none;\n  background: transparent;\n  cursor: pointer;\n}\n\n.card__btn path {\n  fill: var(--main-color);\n}\n\n.card__btn-play {\n  width: 60px;\n  height: 60px;\n  background: var(--main-color);\n  border-radius: 50%;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n}\n\n.card__btn-play path {\n  fill: var(--bg-color);\n}\n  \n  "
