    "css": "/*Card design*/\n.card {\n  width: 200px;\n  height: 300px;\n  background: lightgray;\n  box-shadow: 0 4px 35px rgba(0, 0, 0, 0.2);\n  position: relative;\n  overflow: hidden;\n}\n\n.card > .child {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  transition: clip-path 0.6s;\n  z-index: 1;\n}\n\n.card .card-1 {\n  clip-path: polygon(0% 0%, 75% 0%, 0% 75%);\n}\n\n.card .card-1:hover {\n  clip-path: polygon(0% 0%, 170% 0%, 0% 170%);\n}\n\n.card .card-1:has(~ .card-2:hover),\n.card .card-1:has(~ .card-3:hover) {\n  clip-path: polygon(0% 0%, 15% 0%, 0% 15%);\n}\n\n.card .card-2 {\n  z-index: 0;\n}\n\n.card .card-3 {\n  clip-path: polygon(25% 100%, 100% 25%, 100% 100%);\n}\n\n.card .card-3:hover {\n  clip-path: polygon(-70% 100%, 100% -70%, 100% 100%);\n}\n\n.card .card-1:hover ~ .card-3,\n.card .card-2:hover ~ .card-3 {\n  clip-path: polygon(85% 100%, 100% 85%, 100% 100%);\n}\n\n/*Optional styles*/\n.card {\n  font: 30px Arial, Helvetica, sans-serif;\n}\n\n.card > .child {\n  /*If using background image on card children*/\n  background-size: cover;\n  background-position: center;\n  background-repeat: no-repeat;\n  transition: all 0.6s;\n}\n\n.card .card-1 {\n  background-color: #23a;\n  color: white;\n  padding-top: 30%;\n  padding-left: 20%;\n}\n\n.card .card-1:hover {\n  padding-top: 65%;\n  padding-left: 48%;\n}\n\n.card .card-2 {\n  padding-top: 65%;\n  padding-left: 48%;\n  background-color: #f16;\n}\n\n.card .card-3 {\n  padding-top: 100%;\n  padding-left: 76%;\n  background-color: #dd2;\n}\n\n.card .card-3:hover {\n  padding-top: 65%;\n  padding-left: 48%;\n}\n"
