    "css": ".cards {\n  display: flex;\n  flex-direction: column;\n  gap: 15px;\n}\n\n.cards .red {\n  background-color: #f43f5e;\n}\n\n.cards .white {\n  background-color: #f8f8f8;\n  color: black;\n}\n\n.cards .blue {\n  background-color: #3b22c5;\n}\n\n.cards .card {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-direction: column;\n  text-align: center;\n  height: 200px;\n  width: 300px;\n  border-radius: 10px;\n  color: rgb(1, 1, 1);\n  cursor: pointer;\n  transition: 400ms;\n}\n\n.cards .card p.tip {\n  font-size: 1em;\n  font-weight: 700;\n}\n\n.cards .card p.second-text {\n  font-size: .7em;\n}\n\n.cards .card:hover {\n  transform: scale(1.1, 1.1);\n}\n\n.cards:hover > .card:not(:hover) {\n  filter: blur(10px);\n  transform: scale(0.9, 0.9);\n}"
