    "css": ".card {\n  width: 450px;\n  background: #FFFFFF;\n  box-shadow: 0px 187px 75px rgba(0, 0, 0, 0.01), 0px 105px 63px rgba(0, 0, 0, 0.05), 0px 47px 47px rgba(0, 0, 0, 0.09), 0px 12px 26px rgba(0, 0, 0, 0.1), 0px 0px 0px rgba(0, 0, 0, 0.1);\n  border-radius: 11px;\n}\n\n.search-container {\n  display: flex;\n  align-items: center;\n  justify-content: flex-start;\n  gap: 10px;\n  padding: 0 20px;\n}\n\n.search-container input {\n  width: 100%;\n  height: 50px;\n  border: 0;\n  outline: none;\n  font-size: 13px;\n}\n\n.categories {\n  display: flex;\n  align-items: center;\n  justify-content: flex-start;\n  gap: 5px;\n  padding: 0px 20px 20px 20px;\n}\n\n.categories button {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  padding: 8px 15px;\n  background: #FFFFFF;\n  border: 1px solid #E5E5E5;\n  box-shadow: 0px 0.5px 0.5px #EFEFEF, 0px 1px 0.5px rgba(239, 239, 239, 0.5);\n  border-radius: 20px;\n  font-weight: 600;\n  color: #171718;\n  transition: all 0.6s cubic-bezier(0.15, 0.83, 0.66, 1);\n}\n\n.categories button:hover {\n  transform: scale(1.05) translateY(-3px);\n}\n\n.results {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.results hr {\n  width: 100%;\n  height: 1px;\n  border: 0;\n  background-color: #ECECEC;\n}\n\n.results p {\n  padding: 0 20px;\n}\n\np.label {\n  font-weight: 600;\n  font-size: 11px;\n  line-height: 13px;\n  color: #5F6368;\n}\n\n.results .entry {\n  display: grid;\n  grid-template-columns: 40px 1fr 40px;\n  gap: 12px;\n  padding: 5px 20px;\n  transition: all 0.2s cubic-bezier(0.15, 0.83, 0.66, 1);\n}\n\n.results .entry:hover {\n  background-color: #F5F8FE;\n}\n\n.results .results-list .entry:hover .icon {\n  background-color: #1763fa;\n}\n\n.results .results-list .entry:hover .icon svg path,\n.results .results-list .entry:hover .icon svg circle {\n  stroke: #ffffff;\n}\n\n.results .results-list .entry:hover label {\n  color: #1763fa;\n}\n\n.results .results-list .entry:hover span {\n  color: #7ba0eb;\n}\n\n.results .results-list {\n  display: flex;\n  flex-direction: column;\n}\n\n.results .entry .icon {\n  width: 40px;\n  height: 40px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: #ECECEC;\n  border-radius: 7px;\n  transition: all 0.2s cubic-bezier(0.15, 0.83, 0.66, 1);\n}\n\n.results .entry .desc {\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  gap: 5px;\n}\n\n.results .entry .desc label {\n  display: block;\n  font-weight: 600;\n  font-size: 12px;\n  line-height: 15px;\n  color: #171718;\n}\n\n.results .entry .desc span {\n  font-weight: 600;\n  font-size: 10px;\n  line-height: 12px;\n  color: #72767c;\n}\n\n.results .entry .badge {\n  width: 40px;\n  height: 24px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  margin: auto;\n  background: #DDFFDE;\n  border: 1px solid #08581d0e;\n  border-radius: 7px;\n  font-weight: 700;\n  font-size: 11px;\n  line-height: 13px;\n  text-align: center;\n  color: #08581D;\n}\n\n.card-footer {\n  height: 40px;\n  display: flex;\n  align-items: center;\n  gap: 25px;\n  margin-top: 10px;\n  padding: 0 7px;\n  background: #F8F8F8;\n}\n\n.card .action {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n}\n\n.card .action p {\n  padding-left: 5px;\n}\n\n.card-footer button {\n  width: 24px;\n  height: 24px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 6px;\n  border: 0;\n  background: #ECECEC;\n  outline: none;\n}\n\n.edit-actions {\n  width: 100%;\n  text-align: right;\n  padding-right: 10px;\n  opacity: 0.6;\n}"
