    "css": ".card {\n  width: 17em;\n  height: 22.5em;\n  background: #171717;\n  transition: 1s ease-in-out;\n  clip-path: polygon(30px 0%, 100% 0, 100% calc(100% - 30px), calc(100% - 30px) 100%, 0 100%, 0% 30px);\n  border-top-right-radius: 20px;\n  border-bottom-left-radius: 20px;\n  display: flex;\n  flex-direction: column;\n}\n\n.card span {\n  font-weight: bold;\n  color: white;\n  text-align: center;\n  display: block;\n  font-size: 1em;\n}\n\n.card .info {\n  font-weight: 400;\n  color: white;\n  display: block;\n  text-align: center;\n  font-size: 0.72em;\n  margin: 1em;\n}\n\n.card .img {\n  width: 4.8em;\n  height: 4.8em;\n  background: white;\n  border-radius: 15px;\n  margin: auto;\n}\n\n.card .share {\n  margin-top: 1em;\n  display: flex;\n  justify-content: center;\n  gap: 1em;\n}\n\n.card a {\n  color: white;\n  transition: .4s ease-in-out;\n}\n\n.card a:hover {\n  color: red;\n}\n\n.card button {\n  padding: 0.8em 1.7em;\n  display: block;\n  margin: auto;\n  border-radius: 25px;\n  border: none;\n  font-weight: bold;\n  background: #ffffff;\n  color: rgb(0, 0, 0);\n  transition: .4s ease-in-out;\n}\n\n.card button:hover {\n  background: red;\n  color: white;\n  cursor: pointer;\n}"
