    "css": ".card {\n  font-family: monospace;\n  margin-top: 40px;\n  width: 350px;\n  height: 260px;\n  background: #292828da;\n  border: 2px solid #000;\n  border-radius: 15px;\n}\n\n.top {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin: 10px;\n}\n\n.dots {\n  display: flex;\n  justify-content: last baseline;\n}\n\n.dot {\n  width: 15px;\n  height: 15px;\n  border-radius: 50%;\n}\n\n.dot-1 {\n  background-color: rgb(0, 132, 255);\n}\n\n.dot-2 {\n  background-color: rgb(230, 0, 255);\n}\n\n.dot-3 {\n  background-color: rgb(0, 255, 89);\n}\n\n.top p {\n  font-size: 20px;\n  font-weight: bold;\n}\n\n.dot , .top p {\n  margin: 5px;\n}\n\n.g-color {\n  color: darkgreen;\n}\n\n.bottom {\n  margin-top: 30px;\n  padding: 0 25px;\n}\n\n.code {\n  font-size: 15px;\n}\n\n.red {\n  color: rgb(210, 63, 52);\n}\n\n.violet {\n  color: rgb(181, 40, 203);\n}\n\n.blue {\n  color: rgb(91, 131, 223);\n}\n\n.orange {\n  color: rgb(195, 128, 3);\n}\n\n.white {\n  color: rgb(163, 163, 163);\n}\n\n.space-4 {\n  margin-left: 35px;\n}\n\n.space-4x2 {\n  margin-left: 70px;\n}"
