    "css": ".card {\n  max-width: 320px;\n  display: flex;\n  flex-direction: column;\n  border-radius: 1.5rem;\n  background-color: rgba(0, 0, 0, 1);\n  padding: 1.5rem;\n}\n\n.price {\n  font-size: 3rem;\n  line-height: 1;\n  font-weight: 300;\n  letter-spacing: -0.025em;\n  color: rgba(255, 255, 255, 1);\n}\n\n.lists {\n  margin-top: 2.5rem;\n  display: flex;\n  flex-direction: column;\n  grid-row-gap: 0.75rem;\n  row-gap: 0.75rem;\n  font-size: 0.875rem;\n  line-height: 1.25rem;\n  color: rgba(255, 255, 255, 1);\n}\n\n.list {\n  display: flex;\n  align-items: center;\n}\n\n.list svg {\n  height: 1rem;\n  width: 1rem;\n}\n\n.list span {\n  margin-left: 1rem;\n}\n\n.action {\n  margin-top: 2rem;\n  width: 100%;\n  border: 2px solid  rgba(255, 255, 255, 1);\n  border-radius: 9999px;\n  background-color: rgba(255, 255, 255, 1);\n  padding: 0.625rem 1.5rem;\n  text-align: center;\n  font-size: 0.875rem;\n  line-height: 1.25rem;\n  color: rgba(0, 0, 0, 1);\n  outline: none;\n  transition: all .2s ease;\n}\n\n.action:hover {\n  color: rgba(255, 255, 255, 1);\n  background-color: transparent;\n}"
