    "css": ".card {\n  width: 230px;\n  height: 340px;\n  background: #131313;\n  border: 2px solid #bb6c74;\n  border-radius: 40px;\n}\n\n.image {\n  background-color: #1f1f1fa3;\n  border-radius: 2.5em 2.5em 0em 0em;\n  width: 100%;\n  height: 37%;\n  padding: 2px;\n}\n\n.image svg {\n  width: 75%;\n  margin-top: -25px;\n  margin-left: 30px;\n}\n\n.productTitle {\n  text-align: center;\n  font-size: 22px;\n  font-weight: bold;\n  color: #bb6c74;\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;\n  margin-top: 10px;\n}\n\n.cost {\n  text-align: center;\n  margin-top: 10px;\n  font-weight: bold;\n  color: white;\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;\n}\n\n.radio-inputs {\n  position: relative;\n  margin-top: 20px;\n  margin-left: 13px;\n  display: flex;\n  flex-wrap: wrap;\n  border-radius: 0.5rem;\n  background-color: #1c1c1c;\n  box-sizing: border-box;\n  box-shadow: 0 0 0px 1px rgba(0, 0, 0, 0.06);\n  padding: 0.25rem;\n  width: 200px;\n  font-size: 14px;\n}\n\n.radio-inputs .radio {\n  flex: 1 1 auto;\n  text-align: center;\n}\n\n.radio-inputs .radio input {\n  display: none;\n}\n\n.radio-inputs .radio .name {\n  display: flex;\n  font-weight: 600;\n  cursor: pointer;\n  align-items: center;\n  justify-content: center;\n  border-radius: 0.5rem;\n  border: none;\n  padding: .5rem 0;\n  color: #bb6c74;\n  transition: all .15s ease-in-out;\n}\n\n.radio-inputs .radio input:checked + .name {\n  background-color: #000;\n  color: #fff;\n  font-weight: 600;\n}\n\n.addtocart {\n  width: 100%;\n  margin-top: 19px;\n  padding: 15px;\n  border: none;\n  border-top: 2px solid #bb6c74;\n  background-color: #131313;\n  color: #bb6c74;\n  font-weight: bold;\n  font-size: 15px;\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;\n  border-radius: 0px 0px 38px 38px;\n  transition: 0.2s;\n}\n\n.addtocart:hover {\n  background-color: #bb6c74;\n  border-top: 2px solid transparent;\n  color: #111111;\n}"
