    "css": ".container {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  margin: 30px;\n}\n\n.card {\n  margin: 2%;\n  background: #DBBDBD;\n  width: 70px;\n  height: 100px;\n  box-shadow: 0 2px 3px 0px rgba(0, 0, 0, 0.25);\n  border-radius: 3px;\n  transition: .2s all;\n  cursor: pointer;\n  align-items: center;\n  text-align: center;\n  font-size: 13px;\n  padding-top: 30px;\n}\n\n.card > span {\n  display: block;\n  margin: auto;\n  max-width: 40px;\n}\n\n.container:hover .card {\n  filter: blur(3px);\n  opacity: .5;\n  transform: scale(.98);\n  box-shadow: none;\n}\n\n.container:hover .card:hover {\n  transform: scale(1);\n  filter: blur(0px);\n  opacity: 1;\n  box-shadow: 0 8px 20px 0px rgba(0, 0, 0, 0.125);\n  background: #A82C2C;\n  color: white;\n}"
