    "css": ".plan-card {\n  background: #fff;\n  width: 15rem;\n  padding-left: 2rem;\n  padding-right: 2rem;\n  padding-top: 10px;\n  padding-bottom: 20px;\n  border-radius: 10px;\n  border-bottom: 4px solid #000446;\n  box-shadow: 0 6px 30px rgba(207, 212, 222, 0.3);\n  font-family: \"Poppins\", sans-serif;\n}\n\n.plan-card h2 {\n  margin-bottom: 15px;\n  font-size: 27px;\n  font-weight: 600;\n}\n\n.plan-card h2 span {\n  display: block;\n  margin-top: -4px;\n  color: #4d4d4d;\n  font-size: 12px;\n  font-weight: 400;\n}\n\n.etiquet-price {\n  position: relative;\n  background: #fdbd4a;\n  width: 14.46rem;\n  margin-left: -0.65rem;\n  padding: .2rem 1.2rem;\n  border-radius: 5px 0 0 5px;\n}\n\n.etiquet-price p {\n  margin: 0;\n  padding-top: .4rem;\n  display: flex;\n  font-size: 1.9rem;\n  font-weight: 500;\n}\n\n.etiquet-price p:before {\n  content: \"$\";\n  margin-right: 5px;\n  font-size: 15px;\n  font-weight: 300;\n}\n\n.etiquet-price p:after {\n  content: \"/ handle\";\n  margin-left: 5px;\n  font-size: 15px;\n  font-weight: 300;\n}\n\n.etiquet-price div {\n  position: absolute;\n  bottom: -23px;\n  right: 0px;\n  width: 0;\n  height: 0;\n  border-top: 13px solid #c58102;\n  border-bottom: 10px solid transparent;\n  border-right: 13px solid transparent;\n  z-index: -6;\n}\n\n.benefits-list {\n  margin-top: 16px;\n}\n\n.benefits-list ul {\n  padding: 0;\n  font-size: 14px;\n}\n\n.benefits-list ul li {\n  color: #4d4d4d;\n  list-style: none;\n  margin-bottom: .2rem;\n  display: flex;\n  align-items: center;\n  gap: .5rem;\n}\n\n.benefits-list ul li svg {\n  width: .9rem;\n  fill: currentColor;\n}\n\n.benefits-list ul li span {\n  font-weight: 300;\n}\n\n.button-get-plan {\n  display: flex;\n  justify-content: center;\n  margin-top: 1.2rem;\n}\n\n.button-get-plan a {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  background: #000446;\n  color: #fff;\n  padding: 10px 15px;\n  border-radius: 5px;\n  text-decoration: none;\n  font-size: .8rem;\n  letter-spacing: .05rem;\n  font-weight: 500;\n  transition: all 0.3s ease;\n}\n\n.button-get-plan a:hover {\n  transform: translateY(-3%);\n  box-shadow: 0 3px 10px rgba(207, 212, 222, 0.9);\n}\n\n.button-get-plan .svg-rocket {\n  margin-right: 10px;\n  width: .9rem;\n  fill: currentColor;\n}"
