    "css": ".card {\n  width: 230px;\n  height: 230px;\n  position: relative;\n  background-color: rgb(255, 255, 255);\n  border-bottom: 3px solid #4c6bff;\n  overflow: hidden;\n  -webkit-box-shadow: 0px 12px 65px -39px rgba(0, 0, 0, 1);\n  -moz-box-shadow: 0px 12px 65px -39px rgba(0, 0, 0, 1);\n  box-shadow: 0px 12px 65px -39px rgba(0, 0, 0, 1);\n  border-radius: 5px;\n}\n.BG {\n  width: 100%;\n  height: 100%;\n  position: relative;\n  overflow: hidden;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.BG svg {\n  position: absolute;\n  width: 50%;\n  left: -20%;\n  top: -20%;\n  fill: rgb(244, 244, 244);\n  transition: all 0.5s;\n}\n.content {\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  top: 0;\n  left: 0;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: flex-start;\n  padding: 25px;\n  color: rgb(30, 30, 30);\n  gap: 3px;\n}\n.heading {\n  font-size: 1.4em;\n  font-weight: 700;\n  color: rgb(30, 30, 30);\n}\n.sub-heading {\n  margin-top: -7px;\n  font-size: 0.9em;\n  font-weight: 600;\n  color: rgb(30, 30, 30);\n}\n.sub-sub-heading {\n  font-size: 0.7em;\n  color: rgb(128, 128, 128);\n}\n\n.email {\n  width: 100%;\n  height: 25px;\n  margin-top: 20px;\n  border: none;\n  border-bottom: 1px solid #c0c7ec;\n  outline: none;\n  font-size: 0.7em;\n  background-color: transparent;\n}\n.card-btn {\n  margin-top: 20px;\n  height: 30px;\n  width: 100%;\n  border: none;\n  background: linear-gradient(60deg, #4c6bff, #8196ff);\n  color: white;\n  border-radius: 30px;\n  cursor: pointer;\n}\n\n.card:hover .BG svg {\n  left: 0%;\n  top: 0%;\n  transform: rotate(180deg) scale(9);\n  fill: #c0c7ec;\n}\n"
